package com.gameaggregator.ledgerservice.application;import com.gameaggregator.platform.core.common.exception.NotFoundException;import com.gameaggregator.ledgerservice.api.LedgerDtos.*;import com.gameaggregator.ledgerservice.domain.*;import com.gameaggregator.ledgerservice.infrastructure.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service @Transactional public class LedgerService{final RevenueTransactionRepository txs;final RevenueAllocationRepository allocations;final AdjustmentRepository adjustments;final SettlementRepository settlements;public LedgerService(RevenueTransactionRepository t,RevenueAllocationRepository a,AdjustmentRepository j,SettlementRepository s){txs=t;allocations=a;adjustments=j;settlements=s;}public RevenueTransaction transaction(Transaction r){return txs.save(new RevenueTransaction(r.idempotencyKey(),r.clientId(),r.gameId(),r.amount(),r.currency(),r.occurredAt()));}public RevenueAllocation allocation(UUID id,Allocation r){require(id);return allocations.save(new RevenueAllocation(id,r.beneficiaryId(),r.beneficiaryType(),r.amount()));}public Adjustment adjustment(UUID id,AdjustmentRequest r){require(id);if(r.amountDelta().signum()==0)throw new IllegalArgumentException("Adjustment must change amount");return adjustments.save(new Adjustment(r.idempotencyKey(),id,r.amountDelta(),r.reason(),r.createdBy()));}public Settlement settlement(SettlementRequest r){if(r.periodTo().isBefore(r.periodFrom()))throw new IllegalArgumentException("Invalid settlement period");return settlements.save(new com.gameaggregator.ledgerservice.domain.Settlement(r.beneficiaryId(),r.periodFrom(),r.periodTo(),r.amount()));}public List<RevenueTransaction> transactions(){return txs.findAll();}private RevenueTransaction require(UUID id){return txs.findById(id).orElseThrow(()->new NotFoundException("TRANSACTION_NOT_FOUND","Transaction was not found"));}}